def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits right by shift
    and return the result as a string.
    If shift > number of digits, return digits reversed.
    """
    def digit_list(n):
        return list(str(n))

    def circular_shift_helper(x, shifts):
        return circular_shift_helper(x[1:] + [x[0]], shifts - 1) if shifts > 1 else ''.join(x)

    num_digits = len(str(x))
    digits = digit_list(x)
    shifts = shift % num_digits
    result = circular_shift_helper(digits, shifts)
    if shifts == 0:
        return result
    return result[num_digits - shifts:] + result[:num_digits - shifts]
